示例（Python）：
```python
def validate_function_params(func_name: str, params: dict):
    ALLOWED_FUNCS = {
        'search': {'query': str, 'limit': int},
        'send_email': {'to': str, 'subject': str}
    }
    if func_name not in ALLOWED_FUNCS:
        raise ValueError(f'不允许调用函数: {func_name}')
    for key, expected_type in ALLOWED_FUNCS[func_name].items():
        if key in params and not isinstance(params[key], expected_type):
            raise ValueError(f'参数 {key} 类型错误')
        if isinstance(params.get(key), str):
            check_injection(params[key])  # 注入检测
```

