示例（Python）：
```python
class PromptInjectionDetector:
    def __init__(self):
        self.patterns = [
            r'ignore.*previous.*instructions',
            r'你.*忽略.*之前.*指令',
            r'<\|im_start\|>system',  # 伪造系统消息
            r'```\s*system\s*\n',  # 伪造代码块指令
        ]
        self.encoding_checks = ['base64', 'hex', 'unicode_escape']

    def detect(self, text: str) -> bool:
        # 多编码检测
        for encoding in self.encoding_checks:
            try:
                decoded = text.encode().decode(encoding)
                if self._check_patterns(decoded):
                    return True
            except: pass
        return self._check_patterns(text)
